<?php
require_once dirname(__DIR__, 2) . '/core/bootstrap.php'; Auth::requireLogin();
$db=Database::getInstance()->pdo();
$today=$db->query("SELECT COUNT(*) invoices,COALESCE(SUM(total),0) revenue,COALESCE(SUM(paid),0) paid FROM sales WHERE DATE(created_at)=CURDATE()")->fetch();
$expense=$db->query("SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date=CURDATE()")->fetchColumn();
$customers=$db->query('SELECT COUNT(*) FROM customers')->fetchColumn();
$recent=$db->query('SELECT s.invoice_no,s.total,s.created_at,u.full_name FROM sales s JOIN users u ON u.id=s.user_id ORDER BY s.id DESC LIMIT 8')->fetchAll();
$pageTitle='لوحة التحكم'; require APP_ROOT.'/includes/header.php';
?><div class="page-heading"><div><h1>مرحبا بك، <?= Helper::e(Auth::user()['full_name']) ?> 👋</h1><p>ملخص نشاط المقهى لهذا اليوم · <?= date('Y-m-d') ?></p></div><a class="btn btn-coffee" href="<?= APP_URL ?>/modules/sales/pos.php"><i class="bi bi-plus-lg"></i> بيع جديد</a></div><div class="row g-3 mb-4"><div class="col-md-6 col-xl-3"><div class="stat-card"><div class="label">مبيعات اليوم</div><div class="value"><?= Helper::money($today['revenue']) ?></div><div class="stat-icon"><i class="bi bi-cash-stack"></i></div></div></div><div class="col-md-6 col-xl-3"><div class="stat-card"><div class="label">عدد الفواتير</div><div class="value"><?= (int)$today['invoices'] ?></div><div class="stat-icon"><i class="bi bi-receipt"></i></div></div></div><div class="col-md-6 col-xl-3"><div class="stat-card"><div class="label">مصاريف اليوم</div><div class="value"><?= Helper::money($expense) ?></div><div class="stat-icon"><i class="bi bi-wallet2"></i></div></div></div><div class="col-md-6 col-xl-3"><div class="stat-card"><div class="label">عدد الزبائن</div><div class="value"><?= (int)$customers ?></div><div class="stat-icon"><i class="bi bi-people"></i></div></div></div></div><div class="card"><div class="card-header d-flex justify-content-between"><span>آخر المبيعات</span><a href="<?= APP_URL ?>/modules/sales/index.php">عرض الكل</a></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>رقم الفاتورة</th><th>الكاشير</th><th>التاريخ</th><th>الإجمالي</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?= Helper::e($r['invoice_no']) ?></td><td><?= Helper::e($r['full_name']) ?></td><td><?= Helper::e($r['created_at']) ?></td><td class="fw-bold"><?= Helper::money($r['total']) ?></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="4" class="empty-state">لا توجد مبيعات بعد</td></tr><?php endif; ?></tbody></table></div></div><?php require APP_ROOT.'/includes/footer.php';
